"""Extract WPS cell images by DISPIMG ID. --check compares every generated byte."""
import json, re, sys, zipfile, posixpath
from pathlib import Path
import xml.etree.ElementTree as E
ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / 'docs-source/ticket-capabilities/通用票根接口——所支持类型及字段讲解.xlsx'
check = '--check' in sys.argv
ns = {'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main', 'x':'http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing', 'a':'http://schemas.openxmlformats.org/drawingml/2006/main'}
def output(path, data):
    if check:
        assert path.exists() and path.read_bytes() == data, f'内容不一致: {path}'
    else:
        path.parent.mkdir(parents=True, exist_ok=True); path.write_bytes(data)
with zipfile.ZipFile(SOURCE) as z:
    strings = [''.join(e.itertext()) for e in E.fromstring(z.read('xl/sharedStrings.xml'))]
    cells = {}
    for c in E.fromstring(z.read('xl/worksheets/sheet1.xml')).findall('.//s:sheetData/s:row/s:c', ns):
        v = c.find('s:v',ns)
        value = v.text if v is not None else ''
        if c.get('t') == 's': value = strings[int(value)]
        cells[c.get('r')] = value or ''
    rels = {e.get('Id'):posixpath.normpath('xl/'+e.get('Target')) for e in E.fromstring(z.read('xl/_rels/cellimages.xml.rels'))}
    images = {}
    for pic in E.fromstring(z.read('xl/cellimages.xml')).findall('.//x:pic',ns):
        image_id = pic.find('x:nvPicPr/x:cNvPr',ns).get('name')
        embed = pic.find('x:blipFill/a:blip',ns).get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}embed')
        images[image_id] = rels[embed]
    tickets = []
    for col in 'CDEFGHIJKLMNOPQRSTUVWX':
        code = cells[col+'2']; samples = []
        for row in [1,41]:
            cell = f'{col}{row}'
            if not cells.get(cell): continue
            image_id = re.search(r'DISPIMG\("([^"]+)"',cells[cell]).group(1)
            member = images[image_id]
            filename = f'{code}-{len(samples)+1}{Path(member).suffix}'
            output(ROOT/'public/ticket-capabilities'/filename,z.read(member))
            samples.append({'src':f'/ticket-capabilities/{filename}','thumbnail':f'/ticket-capabilities/{code}-{len(samples)+1}.webp','sourceCell':cell,'imageId':image_id,'sourceMedia':member})
        fields = [{'name':cells[f'A{r}'],'description':cells[f'{col}{r}'],'sourceCell':f'{col}{r}'} for r in range(5,41) if cells.get(f'{col}{r}')]
        tickets.append({'code':code,'name':cells[col+'3'],'sourceColumn':col,'fields':fields,'samples':samples})
    assert len(tickets)==22 and len({t['code'] for t in tickets})==22
    assert sum(len(t['samples']) for t in tickets)==25
    output(ROOT/'src/data/ticketCapabilities.json',(json.dumps(tickets,ensure_ascii=False,indent=2)+'\n').encode())
    print(f'{"校验" if check else "提取"}通过：22 种票根，25 张样张，{sum(len(t["fields"]) for t in tickets)} 个票根字段映射')
